   239→            const corReq = document.getElementById('ideiaCor').value;
   240→            const espReq = document.getElementById('ideiaEspessura').value;
   241→
   242→            if(!nome) return alert("Dê um nome à ideia!");
   243→
   244→            ideias.unshift({ id: Date.now(), nome, link, req: { cor: corReq, espessura: espReq } });
   245→            salvarDados();
