   298→        // --- RENDERIZAÇÃO ---
   299→        function avaliarPossibilidade(req) {
   300→            if(!req.cor || !req.espessura) return '';
   301→            const temLinha = estoque.some(linha => 
   302→                linha.cor.toLowerCase().includes(req.cor.toLowerCase()) && 
