   330→            divIdeias.innerHTML = '';
   331→            ideias.forEach(ideia => {
   332→                const linkTag = ideia.link ? `<a href="${ideia.link}" target="_blank" style="color: var(--primary-dark); font-size: 0.9em;">🔗 Ver Referência/Receita</a><br>` : '';
   333→                divIdeias.innerHTML += `
   334→                    <div class="card">
   335→                        <strong>${ideia.nome}</strong><br>
   336→                        ${linkTag}
   337→                        Precisa de: ${ideia.req.cor || 'N/A'} (${ideia.req.espessura || 'N/A'})<br>
   338→                        ${avaliarPossibilidade(ideia.req)}<br>
   339→                        <button class="btn-delete" onclick="removerIdeia(${ideia.id})">Remover</button>
   340→                    </div>`;
   341→            });
   342→
   343→            // Projetos
   344→            const divProjetos = document.getElementById('listaProjetos');
   345→            divProjetos.innerHTML = '';
   346→            projetos.forEach(proj => {
   347→                let notasHTML = proj.notas.map(n => `<div class="nota-item"><em>${n.data}:</em> ${n.texto}</div>`).join('');
   348→                
   349→                divProjetos.innerHTML += `
   350→                    <div class="card">
   351→                        <strong>${proj.nome}</strong>
   352→                        <div class="progress-container">
   353→                            <label style="font-size: 0.8em;">Progresso: ${proj.progresso}%</label>
   354→                            <input type="range" min="0" max="100" value="${proj.progresso}" onchange="atualizarProgresso(${proj.id}, this.value)">
   355→                        </div>
   356→                        
   357→                        <div style="margin-top: 15px;">
   358→                            <strong>Diário de Bordo:</strong>
   359→                            ${notasHTML}
   360→                            <div style="display: flex; gap: 5px; margin-top: 10px;">
   361→                                <input type="text" id="nota_input_${proj.id}" placeholder="Dificuldades, adaptações..." style="margin: 0;">
   362→                                <button class="btn-primary" style="width: auto;" onclick="adicionarNota(${proj.id})">Salvar</button>
   363→                            </div>
   364→                        </div>
   365→                        
   366→                        <button class="btn-delete" style="margin-top: 15px;" onclick="removerProjeto(${proj.id})">Finalizar/Remover</button>
   367→                    </div>`;
   368→            });
   369→        }
   370→
   371→        renderizarTudo();
