/* Barra de progresso moderna */
.progress-container { margin: 12px 0 6px; }
.progress-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}
.progress-label { font-size: 0.82em; color: #aaa; }
.progress-pct {
    font-size: 0.9em;
    font-weight: bold;
    color: var(--primary-dark);
}
.progress-track {
    width: 100%;
    height: 10px;
    background: #f5d6e0;
    border-radius: 99px;
    overflow: hidden;
    margin-bottom: 8px;
}
.progress-fill {
    height: 100%;
    border-radius: 99px;
    background: linear-gradient(90deg, #ffb6c1, var(--primary-dark));
    transition: width 0.3s ease;
}
input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    height: 4px;
    border-radius: 99px;
    background: #f5d6e0;
    outline: none;
    border: none;
    padding: 0;
    margin: 0;
    cursor: pointer;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--primary-dark);
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(219,112,147,0.45);
    border: 3px solid white;
}
input[type="range"]::-moz-range-thumb {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--primary-dark);
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(219,112,147,0.45);
    border: 3px solid white;
}

/* Fotos do progresso */
.fotos-progresso {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin: 10px 0 6px;
}
.foto-prog-wrap {
    position: relative;
    width: 72px;
    height: 72px;
    border-radius: 10px;
    overflow: hidden;
    flex-shrink: 0;
}
.foto-prog-wrap img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.foto-prog-del {
    position: absolute;
    top: 2px;
    right: 2px;
    background: rgba(0,0,0,0.45);
    color: white;
    border: none;
    border-radius: 50%;
    width: 18px;
    height: 18px;
    font-size: 10px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    line-height: 1;
}
.foto-prog-label {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 14px;
    background: #fff0f5;
    border: 1.5px dashed var(--primary-dark);
    border-radius: 20px;
    color: var(--primary-dark);
    font-size: 0.82em;
    font-weight: bold;
    cursor: pointer;
    margin-top: 4px;
    width: auto;
}
.foto-prog-label:hover { background: #ffe0ec; }

.nota-item { background: #f9f9f9; padding: 8px; border-radius: 5px; font-size: 0.9em; margin-bottom: 5px; border-left: 3px solid var(--primary-dark); }

